import * as React from "react";
import { cx } from "./cx";

export interface ButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {}

/** Flush joined actions. One hairline between. */
export function ButtonGroup({ className, ...props }: ButtonGroupProps) {
  return <div role="group" className={cx("rs-btn-group", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Button group: flush joined actions, one hairline between ── */
.rs-btn-group{display:inline-flex;align-items:stretch}
.rs-btn-group > .rs-btn-primary,.rs-btn-group > .rs-btn-ghost{border-radius:0;margin-inline-start:-1px}
.rs-btn-group > :first-child{margin-inline-start:0}
.rs-btn-group > .rs-btn-primary{position:relative;z-index:1}
